import fs from "node:fs/promises";
import path from "node:path";
import type { SessionStore, StoredSession } from "./sessions.js";

// Conversations used to be one JSON file each. This reads them once so they can be moved into the database.

// Ids are generated by us, so anything else on disk is not ours and must never reach a file path.
const ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

type LegacySession = Omit<StoredSession, "title" | "updated"> & { title?: string; updated?: number };

const isStored = (value: unknown): value is LegacySession => {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string"
    && ID.test(v.id)
    && typeof v.model === "string"
    && typeof v.device === "string"
    && typeof v.root === "string"
    && typeof v.created === "number"
    && Array.isArray(v.history)
    && Array.isArray(v.events)
  );
};

// Reads every stored session. Files that are not valid sessions are skipped, with a warning.
export const loadStored = async (dir: string, warn: (message: string) => void = console.warn): Promise<StoredSession[]> => {
  let names: string[];
  try {
    names = await fs.readdir(dir);
  } catch {
    return [];
  }
  const out: StoredSession[] = [];
  for (const name of names) {
    if (!name.endsWith(".json")) {
      continue;
    }
    try {
      const parsed: unknown = JSON.parse(await fs.readFile(path.join(dir, name), "utf8"));
      if (!isStored(parsed) || `${parsed.id}.json` !== name) {
        throw new Error("not a stored session");
      }
      const firstUser = parsed.events.find((e) => {
        return (e as { type?: string }).type === "user";
      }) as { text?: string } | undefined;
      out.push({ ...parsed, title: parsed.title ?? (firstUser?.text ?? "").replace(/\s+/g, " ").trim().slice(0, 60), updated: parsed.updated ?? parsed.created });
    } catch (err) {
      warn(`[gateway] skipping ${name}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  return out;
};

// Moves the old JSON conversations into the store, once. Afterwards the folder is renamed so it is not read again, and nothing
// is deleted: the files stay where the owner can find them.
export const importLegacySessions = async (dir: string, store: SessionStore, warn: (message: string) => void = console.warn): Promise<number> => {
  const found = await loadStored(dir, warn);
  if (found.length === 0) {
    return 0;
  }
  for (const session of found) {
    await store.save(session);
  }
  await fs.rename(dir, `${dir}.imported`);
  return found.length;
};
